// Units after a number, and a few short words that only ever appear in Keyward's own sentences.
const I18N_UNITS = [[/新增 ?(\d+)/g, 'New: $1'], [/匯入 ?(\d+)/g, 'Import $1'], [/(\d+) ?秒/g, '$1 s'], [/(\d+) ?分鐘/g, '$1 min'], [/(\d+) ?小時/g, '$1 h'], [/(\d+) ?筆/g, '$1 items'], [/(\d+) ?列/g, '$1 rows'], [/(\d+) ?次/g, '$1 times'], [/(\d+) ?個/g, '$1']];
const I18N_SHORT = [['（解鎖）', ' (unlock)'], ['寄至', 'Sent to'], ['請等', 'Wait'], ['明天', 'tomorrow'], ['AI 代理', 'AI agent'], ['· 到 ', '· until '], ['撤銷「', 'After revoking "'], ['刪除「', 'Deleting "']];
const I18N_PUNCT = [['（', ' ('], ['）', ') '], ['，', ', '], ['。', '. '], ['：', ': '], ['；', '; '], ['、', ', '], ['「', '"'], ['」', '"'], ['／', '/'], ['？', '?'], ['！', '!'], ['…', '…']];
const HAS_CJK = /[一-鿿]/;

let UI_LANG = 'zh-TW';

function langPref(){ try { return localStorage.getItem('keyward.lang') || 'auto'; } catch(e){ return 'auto'; } }
function resolveLang(pref){
 if(pref === 'en' || pref === 'zh-TW') return pref;
 const langs = navigator.languages && navigator.languages.length ? navigator.languages : [navigator.language || ''];
 return /^zh/i.test(langs[0] || '') ? 'zh-TW' : 'en';
}

const I18N_LONG = (() => {
 const cjkLen = (s) => (s.match(/[一-鿿]/g) || []).length;
 const keys = Object.keys(I18N_EN).filter(k => cjkLen(k) >= 3).sort((a, b) => b.length - a.length);
 const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
 return new RegExp(keys.map(esc).join('|'), 'g');
})();

// tr translates one piece of rendered text; anything without Chinese passes through untouched.
function tr(s){
 if(UI_LANG !== 'en' || !s || !HAS_CJK.test(s)) return s;
 const t = s.trim();
 if(Object.prototype.hasOwnProperty.call(I18N_EN, t)) return s.replace(t, I18N_EN[t]);
 let out = s.replace(I18N_LONG, (m) => I18N_EN[m]);
 for(const [a, b] of I18N_SHORT) out = out.split(a).join(b);
 for(const [re, b] of I18N_UNITS) out = out.replace(re, b);
 if(out === s) return s; // nothing of ours in it: probably the user's own text
 for(const [a, b] of I18N_PUNCT) out = out.split(a).join(b);
 out = out.replace(/ {2,}/g, ' ').replace(/ ([).,:;])/g, '$1').replace(/\( /g, '(').replace(/([.!?])([A-Z])/g, '$1 $2');
 if(!/\s$/.test(s)) out = out.replace(/\s+$/, '');
 if(!/^\s/.test(s)) out = out.replace(/^\s+/, '');
 return out;
}

const I18N_ATTRS = ['placeholder', 'title', 'aria-label'];
function trNode(n){
 if(n.nodeType === 3){
  const p = n.parentNode;
  if(p && (p.nodeName === 'SCRIPT' || p.nodeName === 'STYLE' || p.closest?.('[data-no-tr]'))) return;
  const v = tr(n.nodeValue);
  if(v !== n.nodeValue) n.nodeValue = v;
  return;
 }
 if(n.nodeType !== 1 || n.hasAttribute('data-no-tr')) return;
 for(const a of I18N_ATTRS){ const v = n.getAttribute(a); if(v && HAS_CJK.test(v)) n.setAttribute(a, tr(v)); }
 if(n.nodeName === 'INPUT' && (n.type === 'submit' || n.type === 'button') && HAS_CJK.test(n.value)) n.value = tr(n.value);
 const walker = document.createTreeWalker(n, NodeFilter.SHOW_TEXT | NodeFilter.SHOW_ELEMENT);
 for(let c = walker.nextNode(); c; c = walker.nextNode()){
  if(c.nodeType === 1){
   if(c.hasAttribute('data-no-tr')) continue;
   for(const a of I18N_ATTRS){ const v = c.getAttribute(a); if(v && HAS_CJK.test(v)) c.setAttribute(a, tr(v)); }
  } else trNode(c);
 }
}

const i18nObserver = new MutationObserver((list) => {
 for(const m of list){
  if(m.type === 'characterData') trNode(m.target);
  else if(m.type === 'attributes') trNode(m.target);
  else m.addedNodes.forEach(trNode);
 }
});

// applyLang sets the language, translates what is on screen, and tells the core (for emails and
// file dialogs). Switching back to Chinese re-renders, since translated text cannot be undone.
function applyLang(pref){
 const prev = UI_LANG;
 UI_LANG = resolveLang(pref);
 document.documentElement.lang = UI_LANG === 'en' ? 'en' : 'zh-Hant';
 document.title = 'Keyward';
 try { window.go?.main?.App?.SetLanguage?.(UI_LANG); } catch(e){}
 i18nObserver.disconnect();
 if(UI_LANG === 'en'){
  trNode(document.body);
  i18nObserver.observe(document.body, {subtree: true, childList: true, characterData: true, attributes: true, attributeFilter: I18N_ATTRS});
 }
 return prev !== UI_LANG;
}
function setLangPref(pref){
 try { pref === 'auto' ? localStorage.removeItem('keyward.lang') : localStorage.setItem('keyward.lang', pref); } catch(e){}
 return applyLang(pref);
}
